It suits clients in the telecommunications and construction industries who need a project management and engineering partner with a long track record in the sector.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://technoline.co.za/about-us/', '$[#]', 'https://technoline.co.za/contact/'), description_enriched_at = datetime('now') WHERE slug = 'technoline-projects-thornton' AND description = 'Technoline Projects is an engineering design, project management and contracting firm based in Thornton, providing turnkey telecoms infrastructure and optical fibre solutions -- including installation work for major fibre network rollouts -- to the cellular and telecommunications industry.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
