-- thai-world-harfield-village (researched)
UPDATE businesses SET description = 'Thai World is a Thai restaurant in Harfield Village, housed in an old house that has been converted into a restaurant, at 49 2nd Avenue on the corner of Surrey Street. The kitchen serves fresh, fragrant dishes full of spices, including red, yellow and green curries with a choice of beef, chicken, seafood, pork or vegetable.

The menu also features rice and noodle dishes, satay and soups, along with different daily specialty dishes that guests can ask about on arrival. The interior is interesting and the atmosphere welcoming, with reviewers describing the staff as incredibly friendly.

It suits diners who want a characterful Thai meal in a converted house setting in Harfield Village, for either lunch or dinner.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.sa-venues.com/things-to-do/westerncape/thai-world/'), description_enriched_at = datetime('now') WHERE slug = 'thai-world-harfield-village' AND description = 'Thai World is a Thai restaurant in Harfield Village serving red, yellow and green curries with a choice of chicken, beef, seafood, pork or vegetables, alongside rice and noodle dishes, satay and soups, with a changing daily special.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
